// --- CONFIGURAÇÃO MESTRE: ODONTOCOMPANY MOGI MIRIM ---
// v1.0 — Agenda única | Google Agenda
const body = $input.item.json.body || $input.item.json;

// 1. LIMPEZA DE DADOS
const telefoneRaw = body.telefone_cliente || body.telefone_contato || body.telefone || '';
const telefoneLimpo = telefoneRaw.toString().replace(/\D/g, '');
const nomePaciente = body.nome_cliente || body.nome_contato || 'Paciente';

// --- FUSO HORÁRIO ---
const TIMEZONE = 'America/Sao_Paulo';

// 2. REGRAS DE HORÁRIO — MOGI MIRIM
// Seg-Sex (1-5): 09:00–12:00 manhã | 13:30–19:00 tarde
// Sábado (6):    08:30–12:00 manhã | sem tarde
// Domingo (7):   Fechado
const REGRAS_MOGI = {
    1: { manha: {ini: {h:9,m:0},  fim: {h:12,m:0}}, tarde: {ini: {h:13,m:30}, fim: {h:19,m:0}} },
    2: { manha: {ini: {h:9,m:0},  fim: {h:12,m:0}}, tarde: {ini: {h:13,m:30}, fim: {h:19,m:0}} },
    3: { manha: {ini: {h:9,m:0},  fim: {h:12,m:0}}, tarde: {ini: {h:13,m:30}, fim: {h:19,m:0}} },
    4: { manha: {ini: {h:9,m:0},  fim: {h:12,m:0}}, tarde: {ini: {h:13,m:30}, fim: {h:19,m:0}} },
    5: { manha: {ini: {h:9,m:0},  fim: {h:12,m:0}}, tarde: {ini: {h:13,m:30}, fim: {h:19,m:0}} },
    6: { manha: {ini: {h:8,m:30}, fim: {h:12,m:0}}, tarde: {ini: {h:0,m:0},  fim: {h:0,m:0}}  },
    7: null
};

// 3. CONFIGURAÇÃO DA AGENDA
const config_agenda = {
    id_agenda: 'c803fdc690bf825b31dcaf9aaea6cc5bb37dc468747086c0dd4c2bed1a81b2c6@group.calendar.google.com',
    nome_unidade: 'OdontoCompany Mogi Mirim',
    nome_empresa: 'OdontoCompany',
    timezone: TIMEZONE,
    regras_horario: REGRAS_MOGI,
    duracao_servico: 30,
    capacidade_simultanea: 1,
    trava_agendamento: 5,
    trava_remarcacao: 2,
    dias_validos: [1, 2, 3, 4, 5, 6],
    profissional: 'Dr. Jonatas / Dra. Rafaela'
};

// 4. TRATAMENTO DE DATAS
let dataFinal = "";
let horaFinal = "";
let dataAntigaBusca = null;

const dataRaw = body.data_iso || body.data_inicio || body.data_agendada;
if (dataRaw) {
    let dt = DateTime.fromISO(dataRaw, { zone: TIMEZONE });
    if (!dt.isValid) dt = DateTime.fromFormat(dataRaw, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
    if (dt.isValid) {
        dataFinal = dt.toFormat('dd/MM/yyyy');
        horaFinal = dt.toFormat('HH:mm');
    }
}

if (body.data_antiga) {
    let dtAntiga = DateTime.fromISO(body.data_antiga, { zone: TIMEZONE });
    if (!dtAntiga.isValid) dtAntiga = DateTime.fromFormat(body.data_antiga, 'dd/MM/yyyy HH:mm', { zone: TIMEZONE });
    if (dtAntiga.isValid) dataAntigaBusca = dtAntiga.toISO();
}

// 5. SAÍDA FINAL
return {
  json: {
    ...body,
    data_agendada: dataFinal,
    horario_agendado: horaFinal,
    data_antiga_iso: dataAntigaBusca,
    telefone_limpo: telefoneLimpo,
    nome_paciente: nomePaciente,
    tipo_agenda: 'mogi_mirim',
    config_agenda: config_agenda,
    acao_fluxo: body.action
  }
};

// --- LÓGICA SCANNER INSTITUTO FRAZÃO v3.0 ---
// Novidade: valida dias válidos para agenda infantil antes de sugerir horários

const itemConfig = $('Configuracao Unidades').first();
const dadosConfig = itemConfig ? itemConfig.json : {};
const configAgenda = dadosConfig.config_agenda || {};

const TIMEZONE = configAgenda.timezone || 'America/Sao_Paulo';
const DURACAO_MINUTOS = configAgenda.duracao_servico || 30;
const CAPACIDADE_MAXIMA = configAgenda.capacidade_simultanea || 2;
const MIN_GAP_MINUTES = 180;
const DIAS_VALIDOS = configAgenda.dias_validos || [1, 2, 3, 4, 5, 6];
const TIPO_AGENDA = dadosConfig.tipo_agenda || 'adulto';

const eventosOcupados = $input.all().map(i => i.json);
const agora = DateTime.now().setZone(TIMEZONE);
const inicioSeguro = agora.plus({ hours: 2 });

function isSlotAvailable(slotStart) {
    let ocupados = 0;
    const slotEnd = slotStart.plus({ minutes: DURACAO_MINUTOS });
    for (const evento of eventosOcupados) {
        if (!evento || !evento.status || evento.status === 'cancelled') continue;
        let iniEvt, fimEvt;
        if (evento.start && evento.start.dateTime) {
            iniEvt = DateTime.fromISO(evento.start.dateTime).setZone(TIMEZONE);
        } else if (evento.start && evento.start.date) {
            iniEvt = DateTime.fromISO(evento.start.date).setZone(TIMEZONE).startOf('day');
        } else { continue; }
        if (evento.end && evento.end.dateTime) {
            fimEvt = DateTime.fromISO(evento.end.dateTime).setZone(TIMEZONE);
        } else if (evento.end && evento.end.date) {
            fimEvt = DateTime.fromISO(evento.end.date).setZone(TIMEZONE).endOf('day');
        } else { continue; }
        if (slotStart < fimEvt && slotEnd > iniEvt) ocupados++;
    }
    return ocupados < CAPACIDADE_MAXIMA;
}

const getMin = (cfg) => cfg.h * 60 + cfg.m;

const dataSolicitadaRaw = dadosConfig.data_agendada;
const horaSolicitadaRaw = dadosConfig.horario_agendado;
let horarioSolicitado = null;

if (dataSolicitadaRaw && horaSolicitadaRaw) {
    horarioSolicitado = DateTime.fromFormat(
        `${dataSolicitadaRaw} ${horaSolicitadaRaw}`,
        'dd/MM/yyyy HH:mm',
        { zone: TIMEZONE }
    );
}

if ((!horarioSolicitado || !horarioSolicitado.isValid) && dadosConfig.data_inicio) {
    horarioSolicitado = DateTime.fromISO(dadosConfig.data_inicio, { zone: TIMEZONE });
}

// ── VALIDAÇÃO DE DIA PARA AGENDA INFANTIL ──────────────────────────────────
// Se o paciente pediu um dia que a Dra. Poly não atende, retornar mensagem
// clara informando os dias válidos — sem sugerir horários incorretos.
if (horarioSolicitado && horarioSolicitado.isValid && TIPO_AGENDA === 'infantil') {
    const diaPedido = horarioSolicitado.weekday;
    if (!DIAS_VALIDOS.includes(diaPedido)) {
        const nomeDias = {1:'segunda',2:'terça',3:'quarta',4:'quinta',5:'sexta',6:'sábado',7:'domingo'};
        const diaLabel = nomeDias[diaPedido] || 'esse dia';
        return {
            json: {
                resultado: `A Dra. Poly atende somente às *terças*, *quartas* e *sextas-feiras* 😊\n\nInfelizmente não temos atendimento infantil na ${diaLabel}.\n\nQual desses dias fica melhor para você?`,
                sugestoes_iso: [],
                horario_solicitado_disponivel: false,
                dia_invalido_infantil: true,
                debug_info: {
                    tipo_agenda: TIPO_AGENDA,
                    dia_solicitado: diaPedido,
                    dias_validos: DIAS_VALIDOS
                }
            }
        };
    }
}
// ──────────────────────────────────────────────────────────────────────────

let solicitadoDisponivel = false;

if (horarioSolicitado && horarioSolicitado.isValid && horarioSolicitado >= inicioSeguro) {
    const diaSem = horarioSolicitado.weekday;
    const regraDia = configAgenda.regras_horario ? configAgenda.regras_horario[diaSem] : null;
    if (regraDia) {
        const minSol = horarioSolicitado.hour * 60 + horarioSolicitado.minute;
        const minFimSol = minSol + DURACAO_MINUTOS;
        const mIni = getMin(regraDia.manha.ini);
        const mFim = getMin(regraDia.manha.fim);
        const tIni = getMin(regraDia.tarde.ini);
        const tFim = getMin(regraDia.tarde.fim);
        const naManha = (minSol >= mIni && minFimSol <= mFim);
        const naTarde = (minSol >= tIni && minFimSol <= tFim);
        if ((naManha || naTarde) && isSlotAvailable(horarioSolicitado)) {
            solicitadoDisponivel = true;
        }
    }
}

let respostaFinal = "";
let sugestoesISO = [];

if (solicitadoDisponivel) {
    const fmt = horarioSolicitado.setLocale('pt-BR').toFormat("dd/MM (ccc)");
    const hora = horarioSolicitado.toFormat("HH:mm");
    respostaFinal = `✅ O horário solicitado está disponível!\n\n🗓️ *${fmt}* às *${hora}*\n\nDeseja confirmar o agendamento?`;
    sugestoesISO = [horarioSolicitado.toISO()];
} else {
    let sugestoes = [];
    let cursorDia = inicioSeguro.startOf('day');
    let diasVerificados = 0;
    const MAX_DIAS_BUSCA = 14; // Aumentado para acomodar agenda infantil com menos dias
    const MAX_OPCOES = 3;

    while (sugestoes.length < MAX_OPCOES && diasVerificados < MAX_DIAS_BUSCA) {
        const diaSemana = cursorDia.weekday;

        // Pular dias inválidos para a agenda atual
        if (!DIAS_VALIDOS.includes(diaSemana)) {
            cursorDia = cursorDia.plus({ days: 1 });
            diasVerificados++;
            continue;
        }

        const regraDia = configAgenda.regras_horario ? configAgenda.regras_horario[diaSemana] : null;
        if (regraDia) {
            const turnos = [regraDia.manha, regraDia.tarde];
            for (const turno of turnos) {
                if (!turno || (turno.ini.h === 0 && turno.ini.m === 0 && turno.fim.h === 0 && turno.fim.m === 0)) continue;
                let loopTime = cursorDia.set({ hour: turno.ini.h, minute: turno.ini.m });
                const fimTurno = cursorDia.set({ hour: turno.fim.h, minute: turno.fim.m });
                while (loopTime.plus({minutes: DURACAO_MINUTOS}) <= fimTurno) {
                    if (sugestoes.length >= MAX_OPCOES) break;
                    if (loopTime >= inicioSeguro && isSlotAvailable(loopTime)) {
                        sugestoes.push(loopTime);
                        loopTime = loopTime.plus({ minutes: MIN_GAP_MINUTES });
                    } else {
                        loopTime = loopTime.plus({ minutes: DURACAO_MINUTOS });
                    }
                }
                if (sugestoes.length >= MAX_OPCOES) break;
            }
        }
        cursorDia = cursorDia.plus({ days: 1 });
        diasVerificados++;
    }

    if (sugestoes.length > 0) {
        const profissional = configAgenda.profissional || 'nossa equipe';
        const linhas = sugestoes
            .map(s => `🗓️ *${s.setLocale('pt-BR').toFormat("dd/MM (ccc)")}* às *${s.toFormat("HH:mm")}*`)
            .join('\n');
        const intro = TIPO_AGENDA === 'infantil'
            ? `O horário solicitado não está disponível. Aqui estão as próximas opções com a ${profissional}:`
            : `O horário solicitado não está disponível. Mas encontrei estas opções:`;
        respostaFinal = `${intro}\n\n${linhas}\n\nQual desses fica melhor para você?`;
    } else {
        respostaFinal = TIPO_AGENDA === 'infantil'
            ? `Não encontrei horários disponíveis com a Dra. Poly nos próximos dias. Posso verificar outro período?`
            : `Não encontrei horários disponíveis para os próximos dias.`;
    }
    sugestoesISO = sugestoes.map(s => s.toISO());
}

return {
    json: {
        resultado: respostaFinal,
        sugestoes_iso: sugestoesISO,
        horario_solicitado_disponivel: solicitadoDisponivel,
        debug_info: {
            gap_utilizado: MIN_GAP_MINUTES,
            tipo_agenda: TIPO_AGENDA,
            dias_validos: DIAS_VALIDOS,
            horario_solicitado: horarioSolicitado ? horarioSolicitado.toISO() : null
        }
    }
};

